/* Theme colors are defined once; all surfaces and controls use semantic tokens. */
.g-root_theme_light {
  --g-color-base-brand: rgb(116, 79, 223);
  --g-color-base-brand-hover: rgb(99, 62, 204);
  --g-color-base-selection: rgb(242, 237, 253);
